\begin{restatable}[{[Block structure of quadratic Bell symmetries]}]{theorem}{productblock}
    \label{thm:product_block}
    Let $\ket{\psi}=\ket{\psi_A}\otimes\ket{\psi_B}$ be a product state across the cut $A|B$. Assume that the state has no stabilizer. Then every quadratic Bell symmetry $M\in\text{Ker}_2(\psi)$ is block-diagonal across the cut $A|B$. Moreover, the two blocks define local quadratic symmetries on the two factors $\ket{\psi_A},\ket{\psi_B}.$
\end{restatable}

\begin{restatable}[{[Clifford-scrambled block diagonalisation]}]{cor}{blockdiagonalisable}
     \label{cor:block-diagonalisable}
    Let $\ket{\psi}=U_C\ket{\psi_A}\ket{\psi_B}$ with no stabilizers. Then every quadratic Bell symmetry $M\in\text{Ker}_2(\psi)$ can be simultaneously block-diagonalised across the cut $A|B$ via congruence with the symplectic transformation given by $C$. 
\end{restatable}

In other words, this property states that the purity of subsystems $A$ and $B$ does not only mean that $\Omega_+^A,\Omega_+^B\in\text{Ker}_2(\psi_A\otimes\psi_B)$, but also that up to the presence of stabilizers, all other symmetries of the state necessarily arise from symmetries of the subsystems. At the level of our Clifford dressed states, this then means that in some basis, the Bell distribution still factorises and this property is preserved.

Importantly, we can always assume the no-stabilizer condition to be satisfied, since our algorithm runs a stabilizer learning protocol on the Bell samples first and finds a Clifford $U_{C'}$ such that
\begin{equation}
    U_{C'}\ket{\psi}=\ket{\psi'}\otimes\ket{0}^{\otimes k},
\end{equation}
for $\ket{\psi'}$ with no stabilizers.

Our computationally efficient algorithm exploits these properties and proceeds by performing \emph{simultaneous block-diagonalisation} (SBD) of $\text{Ker}_2(\psi)$ in order to find potential structure arising from pure subsystems. We show that, by treating the symmetries as linear operators, we can phrase the SBD problem in terms of a module decomposition, allowing us to use tools from finite algebras in order to tackle this \cite{chistov1997polynomial,ronyai1990computing,wilson2008finding}. 

We then first show that for some $\ket{\psi}=U_C\ket{\psi_A}\otimes\ket
\psi_B$, we do not need to find the finest SBD of $\text{Ker}_2(\psi)$ in order to recover $A,B,U_C.$

\begin{lemma}[{[Efficient simultaneous block diagonalisation} (Informal version of \Cref{lemma:bilinear_to_linear,lemma:simple_comp,lemma:efficient_SBD})]
    \label{lemma:SBD_summary}
    Given $\text{Ker}_2(\psi)=\text{span}_{\mathbb F_2}\{M_i\}_{i=1}^{d_{\text{Ker}}}$ for some state vector $\ket{\psi}$. We can define $T_i:=\Omega(M_i+M_i^T)$, and consider the algebra
    \begin{equation}
        \mathfrak t:=\text{span}_{\mathbb F_2}\langle T_i\rangle_{i=1}^{d_{\text{Ker}}}.
    \end{equation}
    Then,
    \begin{equation}
        \mathfrak e :=\{\phi\in\text{End}_{\mathbb F_2}(\mathbb F_2^{2n}):\phi a=a\phi,\forall a\in\mathfrak t\}
    \end{equation}
    is an associative algebra that uniquely splits into some nilpotent radical $R$ and some simple components $S_i$
    \begin{equation}
        \mathfrak e=S_1\oplus\dots\oplus S_m\oplus R.
    \end{equation}
    Each component $S_i$ defines some $\mathfrak t$-invariant subspaces $V_i\subseteq \mathbb F_2^{2n}$, and in the basis defined by them, $\mathfrak t$ is block-diagonal. Moreover, if the change of basis is symplectic, then $\text{Ker}_2(\psi)$ is also block-diagonal. While this is not necessarily the finest SBD of $\text{Ker}_2(\psi)$, if the state is of the form $\ket{\psi}=U_C\ket{\psi_A}\otimes\ket{\psi_B}$, then one of the block-diagonal cuts found in this way must correspond to the partition $A|B.$ Finally, all of this can be computed in time $\text{poly}(n).$
\end{lemma}

The algorithm in \Cref{lemma:SBD_summary} in general will return a transformation $A\in GL(2n,\mathbb F_2)$ performing the SBD, not necessarily a symplectic one. We will show that since the decomposition is unique, given this $A$, it is then easy to find a symplectic change of basis $C\in \text{Sp}(2n,\mathbb F_2)$. Moreover, for a state vector $\ket{\psi}=U_C\ket{\psi_A}\otimes\ket{\psi_B}$, any such $C$ not only block-diagonalises $\text{Ker}_2(\psi)$, but also forces $\Omega_+^A,\Omega_+^B$ to be symmetries of the block-diagonalised kernel, and hence gives us a disentangling Clifford.

We at this point subsume all of this in the following theorem.
\begin{restatable}[{[Polynomial-time recovery of hidden Clifford-product structure]}]{theorem}{blockdiagonalisesym}
    \label{thm:block_diagonalisation_product}
    Given a basis $\{M_i\}_{i=1}^{d_{\text{Ker}}}$ of $\text{Ker}_2(\psi)$, for some $n$-qubit pure state vector $\ket{\psi}$, there exists an algorithm running in time $\text{poly}(n)$ that finds, if it exists, a symplectic operation $\tilde C\in\text{Sp}(2n,\mathbb F_2)$ that simultaneously block-diagonalises $\{M_i\}_{i=1}^{d_{\text{Ker}}}$. For a state of the form $\ket{\psi}=U_C\bigotimes_{i=1}^m\ket{\phi_i}_{c_i}$, satisfying the conditions in \Cref{def:learning_task}, this procedure finds blocks corresponding to each $c_i$, and a Clifford unitary $U_{\tilde C}^{\dagger}$ which necessarily disentangles $\ket\psi$ across the $c_i$'s.
\end{restatable}

We can then finally show that the number of copies of $\ket{\psi}$ required to solve tasks in \Cref{def:testing_task,def:learning_task} by an algorithm relying on the techniques above is polynomially bounded, and thus our algorithms are fully efficient.

\begin{restatable}[{[Efficient testing]}]{theorem}{maintesting}
    \label{thm:testing_alg}
    Let $\ket{\psi}$ be a state that is of the form $U_C\ket{\psi_A}\otimes\ket{\psi_B}$ as in \Cref{def:testing_task} (A) or $\epsilon$-far from it in $2$-norm for any choice of $U_C,\psi_A,\psi_B$ (B). Then, there is an algorithm running in time $\text{poly}(n,\frac{1}{\lambda},\log\frac{1}{\delta})$, such that given access to $N=O(\frac{1}{\lambda^2}(n^2+\log(1/\delta)))$ copies of the state, for $\lambda=\min(\eta,\epsilon)$ determines if $\ket{\psi}$ is in Case A or Case B with probability at least $1-\delta.$
\end{restatable}

\begin{restatable}[{[Efficient learning]}]{theorem}{mainlearning}
    \label{thm:learning_alg}
    Let $\ket{\psi}=U_C\left(\bigotimes_{i=1}^m\ket{\psi_i}_{c_i}\right)$ satisfying the stabilizer condition in \Cref{def:learning_task}. Then, there is an algorithm running in time $\text{poly}(n,\frac{1}{\lambda},\log\left(\frac{1}{\delta}\right))$, for $\lambda=\min(\eta,\epsilon/\sqrt{n})$, such that given access to $N=O\left(\frac{1}{\lambda^2}(n^2+\log\left(\frac{1}{\delta}\right))\right)$ many copies of $\ket{\psi}$, outputs a Clifford unitary $U_{\tilde C}$ and a set partition $\{\tilde c_i\}_{i=1}^{m'}$ ($m'\geq m$) satisfying $||\ket{\psi}-U_{\tilde C}\bigotimes_{i=1}^{m'}\ket{\phi_i}_{\tilde c_i}||_2\leq \epsilon$, for some choice of $\{\phi_i\}_{i=1}^{m'}$, with probability at least $1-\delta.$

\end{restatable}

The sample analysis of \Cref{thm:testing_alg} and \Cref{thm:learning_alg} is split in two main parts. First, we show that $\text{poly}(n,\frac{1}{\epsilon},\log\frac{1}{\delta})$ many samples are enough for an exhaustive search algorithm to succeed. Indeed, for that number of samples, only symmetries $M=C^{-T}(\Omega_+^S+\lambda_C)C^{-1}$ incurring an error at most $\epsilon$, are observed in $\text{Ker}_{2,N}(\psi)$ (the subindex $N$ distinguishes the finite sample kernel from the ideal one), and hence an algorithm that simply performs brute-force search succeeds with probability $1-\delta.$ In a subsequent step, we show that the properties of \Cref{cor:block-diagonalisable} also hold with high probability with a bounded number of samples. These are then enough to prove the overall efficiency of our algorithm, which we describe in detail in \Cref{alg:hidden-clifford-test}.

Note that the algorithm in \Cref{thm:learning_alg} only learns a description of the disentangling Clifford, and the partitions, however this can easily be lifted to a full state learning algorithm by using results from \cite{bakshi2025learning}. 

\begin{restatable}[{[Full state learning]}]{cor}{learningstates}
    \label{cor:state_learning}
    Let $\ket{\psi}$ be of the form in \Cref{def:learning_task}, with $|c_i|=\log_2d,\forall i$. Then, for any $\epsilon \in (0,1/\sqrt{3})$, using \Cref{alg:hidden-clifford-test} and Algorithm 4.19 in Ref.~\cite{bakshi2025learning}, a full description $\ket{\phi}$ such that
    \begin{equation}
        ||\ket{\psi}-\ket{\phi}||_2\leq\epsilon
    \end{equation}
    can be learnt with success probability at least $1-\delta$ with a sample complexity of $N=O\big(\frac{1}{\lambda^2}(n^2+\frac{m'd}{\lambda^2}\log\frac{1}{\delta})+m'd^2\log\frac{m'}{\delta}\big)$ and in time $\text{poly}(n,d,\frac{1}{\lambda},\log\frac{1}{\delta})$, for $\lambda=\min(\eta,\epsilon/\sqrt{n})$.
\end{restatable}
Note that in \Cref{cor:state_learning} we assume all the partitions to be of the same size for simplicity, but the result holds in general. This then not only allows us to learn states of this form, but also certain unitaries given access to their Choi state. Indeed, given any unitary of the form
\begin{equation}
    \label{eqn:conjugated_product_U}
    U=U_{C_1}\bigg(\bigotimes_iU_i\bigg)U_{C_2},
\end{equation}
its Choi state has the form in \Cref{def:learning_task}, since
\begin{equation}
    \ket{\Phi_U}=U_{C_1}\bigg(\bigotimes_iU_i\bigg)\otimes U_{C_2}^T\ket{\Phi_0}=(U_{C_1}\otimes U_{C_2}^T)\bigotimes_i\ket{\Phi_{U_i}},
\end{equation}
and thus, for the right $\ket{\Phi_{U_i}}$, $\ket{\Phi_U}$ can be learnt efficiently. The ability to learn such Choi states allows us to use some disentangling techniques introduced in Ref.~\cite{fux2025disentangling}, in order to show some striking implications of our algorithms for $T$-doped Clifford unitaries.  

\begin{restatable}[{[Learning from algebraically independent Pauli rotations} (Informal version of \Cref{lemma:disentangling} and \Cref{lemma:properlearning})]{theorem}{independentpaulis}
    \label{thm:independent_pauli_learning}
Given a $k$-doped Clifford unitary $U=U_{C_1}\cdot T\cdot\dots \cdot U_{C_k}\cdot T\cdot U_{C_{k+1}}$, with $k\leq 2n$, this can always be written as $U=U_C\prod_{i=1}^k e^{i\pi/8P_i}$. Then if the Paulis $\{P_i\}_{i=1}^k$ are algebraically independent, then the Choi state of $U$ has the form in \Cref{def:learning_task}, and a proper description of $U$ in terms of $U_C$ and $\{P_i\}_{i=1}^k$ is efficiently learnable using \Cref{alg:hidden-clifford-test} and \Cref{cor:state_learning}. Moreover, this still works arbitrary Pauli doping $\{e^{i\theta_iP_i}\}_{i=1}^k.$
\end{restatable}

Indeed, we show that some $T$-doped unitaries, in spite of exhibiting large amounts of entanglement or magic, still have a Choi state retaining a hidden Clifford-product structure, and hence remain efficiently learnable. Importantly, our proper learner does not rely solely on a global approximation of $\ket{\Phi_U}$, but rather performs state tomography on single-qubit factors, thereby providing direct control of the induced channel error. Under the exact $T$-doped promise, these factors belong to a finite, constantly separated family, so a proper description of $U$ can be identified exactly with high probability. More generally, for continuously parametrized Pauli rotations, the angle-estimation errors accumulate only linearly, so estimating each factor to accuracy $\epsilon/k$ yields an $\epsilon$ approximation in diamond norm.

Finally, we show that the condition that the Paulis are algebraically independent, and hence this structure, is maintained with high probability over the choice of Cliffords, at regimes well beyond the standard $O(\log(n))$-doped regime.
\begin{restatable}[{[Probability of algebraic independence]}]{lemma}{independentpauliprobabilities}
    For a $k$-doped Clifford unitary $U=U_{C_1}\cdot T\cdot\dots \cdot U_{C_k}\cdot T\cdot U_{C_{k+1}}$, with $U_{C_i}$ chosen uniformly at random from the Clifford group, the Pauli operators $\{P_i\}_{i=1}^k$ after conjugating the $T$ gates through, are algebraically independent with probability 
    \begin{equation}
        \label{eqn:success_p}
        p=\prod_{i=0}^{k-1}\left(1-\frac{2^i-1}{4^n-1}\right).
    \end{equation}
\end{restatable}

\begin{restatable}[{[Typical learnability of $T$-doped Clifford circuits]}]{cor}{probabilities}
    \label{cor:t_doped_probability}
    Given $k-$doped Clifford unitaries of the form $U=U_{C_1}\cdot T\cdot\dots \cdot U_{C_k}\cdot T\cdot U_{C_{k+1}}$, with $U_{C_i}$ chosen uniformly at random from the Clifford group, they can be efficiently learnt using the algorithm in \Cref{cor:state_learning} with:
    \begin{itemize}
    \item $1-O(\frac{1}{2^{c n}})$ success probability, if  $k\leq 2n-c n$ with $c>0$.
    \item $1-O(\frac{1}{n^c})$ success probability, if $k\leq 2n-c\log n$ with $c>0$.
    \item $\Theta(1)$ success probability, if $k\leq 2n-c$ with $c\geq0$.
\end{itemize}
\end{restatable}

\begin{algorithm}[t]
\caption{Computationally efficient algorithm for task in \Cref{def:learning_task}}
\label{alg:hidden-clifford-test}
\begin{algorithmic}[1]

\Statex \textbf{Input:} 
\(N=O(\frac{1}{\lambda^2}(n^2+\log(1/\delta)))\), for $\lambda=\min(\eta,\epsilon/\sqrt{n})$ copies of some state vector $\ket{\psi}.$ 

\Statex \textbf{Promise:} 
There exist a Clifford $U_C$, and some partition $\{c_i\}_{i=1}^m$ such that for some $\{\psi_i\}_{i=1}^m$ it holds that $\ket{\psi}=U_C\bigotimes_{i=1}^m\ket{\psi_i}_{c_i}$. Moreover, $\forall P\in\mathcal P_n$ either $|\langle P\rangle_\psi|=1$ or $|\langle P\rangle_\psi|\leq1-\eta$.
\Statex \textbf{Output:} 
A Clifford $U_{\tilde C}$ and a partition $\{\tilde{c}_i\}_{i=1}^{m'}$ for $m'\geq m$ such that $||U_{\tilde C}\bigotimes_{i=1}^{m'}\ket{\phi_i}_{\tilde{c}_i}-\ket{\psi}||_2\leq\epsilon$, for some $\{\phi_i\}_{i=1}^{m'}.$

\State Perform Bell sampling on the copies of $\ket{\psi}.$

\State Run stabilizer learning algorithm to precision $\eta$ on the samples.

\State After stabilizer learning $\exists U_{C_1}^{\dagger}$ such that $ U_{C_1}^\dagger\ket\psi=\ket{\tilde\psi}\otimes\ket{0}^{m_1}$. Construct a basis of $\text{Ker}_{2,N}(\tilde\psi).$

\State Run the SBD algorithm on $\text{Ker}_{2,N}(\tilde\psi).$
\State Let $C_2$ be the block-diagonalising matrix output above, and $c'_i$ with $i\in[m_2]$ be the blocks.
\State Compute $\text{Ker}_{2,N}(U_{C_2}^\dagger\ket{\tilde\psi})$.

\For{$i\in[m_2]$}
    \State $P_i:=\Omega_+^{c'_i}$
\EndFor
  \State Solve the linear system $\sum_{i=1}^{m_2}s_iP_i\in\text{Ker}_{2,N}(U_{C_2}^\dagger\ket{\tilde\psi})$, with unknowns $\mathbf s=(s_1,\dots,s_{m_2})\in\mathbb F_2^{m_2}$.


\State \textbf{return} $U_{\tilde C}=U_{C_1}\cdot U_{C_2}$ \textit{and} $\{\tilde c_i\}_{i\in[m']}$ for $m'\leq m_1+m_2$, such that the corresponding subsystems are found pure.

\end{algorithmic}
\end{algorithm}

\subsection{Discussion and future work}

\paragraph{Hidden structure beyond conventional low-resource regimes.} Our results identify a family of efficiently learnable quantum states whose structure is not captured by any of the usual notions of low complexity. Namely, the states in \Cref{def:learning_task} can exhibit substantial entanglement, magic, and non-Gaussianity. Nevertheless, the hidden product structure leaves strong signatures in its Bell distribution, 
which can be retrieved efficiently.

Our approach to do so admits a crisp interpretation within the abelian StateHSP framework of Ref.~\cite{hinsche2026abelian}, but 
requires additional reconstruction beyond the ordinary hidden-cut problem. Accommodating the unknown Clifford enlarges the ambient group to account for all genuinely quadratic forms, and obscures the relation between the recovered symmetries and the underlying tensor-product structure. Our simultaneous-block diagonalisation step exploits the structure of the quadratic constraints to efficiently recover a frame in 
which the subsystem purity equations become explicit. 

This result can be, first of all, interpreted 
as an obstruction to a gluing lemma for Cliffords. 
It would be natural to think, given the high resource content that states in \Cref{def:learning_task} can have due to the mismatch between Cliffords and product unitaries, that a state like $U_C\bigotimes_i\ket{\psi_i}$ would be hard to learn. Potentially, by choosing $\{\ket\psi_i\}_i$ to be pseudorandom and using $U_C$ as a scrambling unitary, a plausible hypothesis would be that the transformed state would also be globally pseudorandom. Our result clearly disproves this and shows not only that Cliffords can't erase all evidence of the underlying factorisation, but also that this information can be efficiently accessed.

In this sense our results are closely related to those in Ref.~\cite{grewal2025efficient}, which gives efficient algorithms for learning unitaries of the form
\begin{equation}
    \label{eqn:unitaries}
    V=U_C^tU_d,\quad W=U_dU_C^t,
\end{equation}
where $U_C^t$ is a $t$-doped Clifford, and $U_d$ a depth-$d$ circuit. Their algorithm already showed that these apparently highly resourceful unitaries remained structured, and likewise identify certain block-structures in the Pauli expansion of operators related to $V$ and $W.$ Their work admits controlled departures from the exact Clifford and product regimes, by allowing modest amounts of magic and entanglement, but assumes a stronger oracle model of access to the unitaries and their inverses. Our work restricts to the exact case (exact Clifford and product) but works with a significantly weaker access model, that is only state access. This then also allows us to do unitary learning without demanding oracle access to the unitary or its inverse, but just its Choi state. Moreover, while their algorithm is improper, our method can sometimes manage to output a description of $V$ in terms of $U_C$ and $\bigotimes_iU_i$, as we show for the $t$-doped circuit case. 

\paragraph{Consequences for $T$-doped Clifford circuits.} \Cref{thm:independent_pauli_learning} and \Cref{cor:t_doped_probability} deeply challenge previously established beliefs on the learnability of this class of circuits \cite{lai2022learning,leone2024learningstates,leone2024learning}. Indeed, general efficient learning algorithms were only known for $t$-doped circuits with $t=O(\log n)$, via compression methods. While these algorithms work at $t\sim n$, the runtime grows exponentially, deeming this regime quasi-chaotic \cite{leone2024learning}. The $t\sim 2n$ limit is then commonly associated with the onset of chaotic behaviour and no generic learning algorithm is believed to exist.

While our results do not contradict worst-case hardness in these regimes, they show that a large family of circuits of this type retains an efficiently recoverable compressed description well beyond the limit of $t=O(\log n)$, in terms of states of the form in \Cref{def:learning_task}. Moreover, far from being an isolated effect, an exponentially big fraction of these circuits satisfy this in the \textit{quasi-chaotic} regime ($t\sim n$), and still a constant fraction in the \textit{chaotic} case ($t\sim 2n$), and hence can be learnt efficiently. Besides these cases, our algorithm can still learn certain circuits in the setting where $t>2n$. For instance, whenever the algebraic dependencies breaking the underlying product structure would remain confined in subsystems of $O(\log n)$ many qubits, the unitaries could still be learnt. It could then be relevant to study, for instance, what circuits in this class satisfy this property.

In this regard our work also closely 
connects to Ref.~\cite{lee2025learning}, where efficient learning algorithms are given for states with higher doping than $O(\log(n))$, albeit for the restricted case where these can be written as $\ket{\psi}=T^{\otimes\vec i}U_C\ket{0}^{\otimes n}$. Certain members of this state family are also accessible to our framework after conjugating the $T$ gates through. Moreover, the corresponding unitary family $U=T^{\otimes\vec i}U_C$ is subsumed by our \Cref{thm:independent_pauli_learning}. Their approach however, differs significantly from ours by looking at the problem as a non-abelian 
StateHSP instance. We believe that exploring these connections could be interesting to understand the full reach of efficient learnability of $t$-doped circuits.

\paragraph{Benchmarking resource-rich regimes and logical sectors.} We believe that our results may also be relevant in practical scenarios, by enabling probes of previously inaccessible regimes. Many benchmarking and certification methods need to exploit some efficiently accessible description of the states and circuits to remain scalable. To date, these have then been restricted, mostly to low-resource regimes, relying on low-bond-dimension MPS, almost stabilizer structure, or Gaussianity of states \cite{eisert2020quantum,aolita2015reliable,cramer2010efficient,flammia2011direct,kliesch2021theory}. Nevertheless, the states and unitaries that we consider here can still look highly complex according to any such description, and hence our methods could provide access to a regime complementary to that of previous works. This could be especially relevant for designing new benchmarking protocols for instance for the early fault-tolerant regime \cite{mills2025logical,harper2019fault,leitch2026learningunknownstabilizercodes}, where extending the reach of previous techniques will likely be required. 

A natural task for our algorithm in that setting would for instance be to perform learning of logical product states of stabilizer error correcting codes \cite{gottesman1997stabilizer}. Indeed, if $U_C$ is the Clifford encoding circuit of a stabilizer code, and the logical state factors across logical subsystems, then its physical realization is of the form
\begin{equation}
    \ket{\psi}=U_C\left(\bigotimes_i\ket{\phi_i}_{L}\otimes\ket{0}_{\text{aux}}\right),
\end{equation}
which can be learnt by \Cref{alg:hidden-clifford-test}. Recovering the hidden factors, could therefore be used to certify the absence of spurious correlations between distinct logical subsystems, in a completely code agnostic way, even when the systems are not physically separated.

\paragraph{Hamiltonian property learning.}

Other potential applications of our algorithm include the study of many-body systems, where one might be interested in learning some Hamiltonian $H$, or at least some of its properties. A broad range of methods has been developed for this purpose \cite{wiebe2014hamiltonian,bairey2019learning,anshu2021sample,huang2023learning,haah2024learning, hu2025ansatz,bluhm2026certifying, bluhm2026hamiltonian, ma2024learning, franca2024efficient}, but their guarantees typically rely on short evolution times, or strong structural facts such as locality or sparsity in some other specified operator basis. For Hamiltonians of the type
\begin{equation}
    H=U_C\left(\sum_S H_S\otimes \mathbb I_{S^c}\right)U_C^\dagger,
\end{equation}
where common promises might not hold, our \Cref{alg:hidden-clifford-test} can still manage to learn $H$ given access only to its forward time evolution operator, at almost arbitrary times. While the algorithms in Ref.~\cite{grewal2025efficient} could also be used for this purpose, the fact that our algorithm does not rely on inverse time access makes it significantly more amenable to be run in practice. 

Moreover, even when full Hamiltonian learning might still not be possible, our methods can still help us finding decoupling strategies that drastically compress the system and reduce its simulation cost for instance. These phenomena have been studied recently in the context of critical spin chains \cite{fan2025disentangling,kim2026disentangling}, where it has been shown that $XX$-type Hamiltonians can decouple exactly into two distinct Ising chains under the action of a Clifford, in approaches building on earlier related work disentangling fermionic systems
\cite{PhysRevLett.117.210402}.
Our algorithm could then enable practical exploration of these hidden symmetries for more families of systems.

\paragraph{Open questions.}
Whether or not our guarantees can be extended to a robust setting is one of the main open questions we leave for the future. As we already stated, in Ref.~\cite{bakshi2025learning}, an efficient learning algorithm is given also for the case where the Cliffords showcase some amount of magic and the product structure is slightly perturbed to have some entanglement. This is only possible in their case given full oracle access to the unitary and its inverse. In our case, under these perturbations, namely for state vectors 
of the form
\begin{equation}
    U_C^tU_d\ket{0}^{\otimes n},
\end{equation}
with $U_C^t$ a $t$-doped Clifford, and $U_d$ an arbitrary depth-$d$ circuit, for $t,d$ small enough, the exact quadratic constraints become noisy. Recovering them by our method then leads to a parity-learning problem resembling learning parity with noise (LPN) \cite{blum1994lpn}. This identifies a clear computational obstruction for our algorithm to work in that case, albeit some more involved protocols could potentially overcome this. We conjecture however, that any such method necessarily runs into similar computational issues, rendering these states hard to learn. 

States of this form live in the first level of the magic hierarchy introduced in Ref.~\cite{parham2026quantum}, and understanding their learnability would have strong implications for questions across a wide range of fields, like cryptography, or resource theories. In the latter context, these states have recently received significant amount of attention under the name of \emph{Clifford augmented MPS} (CAMPS) \cite{qian2024camps,masot2026limits,fux2025disentangling,liu2026camps,fan2025disentangling,kim2026disentangling}, as they have been argued to be a better ansatz for bounding the simulation complexity of some many-body systems, and thus solving this conjecture would shed some light on the interplay between simulability and learnability of quantum states.

A further open question is whether the same strategy admits a genuinely fermionic formulation. In particular, can analogous quadratic symmetries in the Majorana representation be efficiently sampled and simultaneously block-diagonalised so as to recover a hidden tensor-product or mode decomposition up to a fermionic Gaussian transformation? Such an extension could provide learning and disentangling algorithms directly in the fermionic setting, without first mapping the system to qubits, while naturally incorporating fermionic parity and the absence of an ordinary subsystem tensor-product structure of fermionic modes. Also in that case, extensions to related free fermionic augmented MPS \cite{PhysRevLett.117.210402} could be interesting.

Finally, on a more technical note, our analysis gives an explicit transformation between quadratic symmetries of the Bell distribution and quadratic symmetries of the Pauli distribution, showing that its image is a proper subset of the latter. In particular, some properties of the Pauli distribution cannot be straightforwardly inferred from quadratic symmetries of the Bell samples. A better characterization of this, would sharpen our understanding of which nonlinear properties of pure states are accessible through Bell measurements. We conjecture that all quadratic Bell constraints necessarily reduce to stabilizer and subsystem purities (up to affine transformations). Proving this, would both simplify the analysis developed here, and clarify the intrinsic information content of the Bell distribution. Conversely, finding genuinely different families of symmetries, would then point to new classes of structured states admitting similar efficient learning algorithms.

\subsection*{Structure of 
this work}

We introduce some preliminaries about Bell sampling in \Cref{sec:bell_sampling}. We introduce our framework of quadratic Bell symmetries and generalized purities and show how some canonical examples fit into it. In \Cref{sec:clifford_dressed} we then introduce the family of states that we care about and show how they are still structured in a very particular way. Given this structure we already show here that there exists an exponential runtime algorithm requiring only access to polynomially many copies in order to retrieve it. In \Cref{sec:comp_eff} we lift this to an algorithm running in polynomial time. We introduce the required finite algebra background and show the simultaneous block-diagonalisation procedure. We complete the section showing that the sample complexity of this algorithm is still polynomial. We finalize in \Cref{sec:Tdoped} by showing how to disentangle the Choi states of $T$-doped unitaries, and how to use this to come up with a proper learning algorithm for them.

\section{Bell sampling}

\label{sec:bell_sampling}

We now introduce Bell sampling and its associated probability distribution, which form the foundation of our entire framework. Bell sampling has emerged as a remarkably powerful primitive in quantum learning theory: collective measurements on pairs of copies can reveal algebraic structure that is inaccessible to ordinary single-copy measurements, enabling, among other applications, efficient stabilizer learning and testing, fidelity estimation, and the recovery of hidden tensor-product structure \cite{montanaro2017learning,gross2021schur,grewal2024improved,grewal2025efficient,hangleiter2024bell,hinsche2025efficient,hinsche2026abelian}. In our setting, its central role is that the Bell distribution retains precise quadratic signatures of purity and product structure even after an unknown Clifford transformation has obscured the underlying tensor-product decomposition.

\begin{definition}[{[Bell distribution $\mathsf b_\rho$]}]
    \label{def:bell_dsitribution}
    Let $\rho$ be some state on $n$ qubits. Then let $d=2^n,$ and
    \begin{equation}
        \ket{\Phi}=\frac{1}{\sqrt d}\sum_{x\in\{0,1\}^n}\ket{x}\ket{x}
    \end{equation}
    be the maximally entangled state on two copies of an $n$-qubit system. For all $n-$qubit Pauli operators 
    \begin{equation*}
    \ket{\Phi_P}=(P\otimes \mathbb I)\ket{\Phi},
    \qquad P\in\mathcal P_n .
\end{equation*}
define the full basis of Bell states on $2n$-qubits. 

Then, given two copies of the state $\rho$, Bell sampling performs measurements of $\rho\otimes\rho$ in the Bell basis. The Bell distribution of $\rho$ is then defined as the probability distribution resulting from these measurements
\begin{equation}
\mathsf b_\rho(\Phi_P)=\Tr\!\left[\ket{\Phi_P}\!\bra{\Phi_P}\,\rho\otimes\rho\right]=\frac{1}{d}\Tr\!\left[P\rho P\rho^T\right].
\end{equation}
\end{definition}
Since all Bell states can be labeled by their corresponding Pauli, slightly abusing notation, from now on we will label the Bell distribution using Paulis directly. In spite of this, one should take care to not confuse this with the Pauli distribution of a state, i.e.,
\begin{equation}
    \mathsf P_\rho(P)=\frac{1}{d}\text{Tr}[P\rho]^2.
\end{equation}
This difference becomes particularly clear for pure states $\rho=\ket\psi\!\!\bra\psi$, for which the Bell distribution reduces to 
\begin{equation}
    \label{eqn:pure_Bell}
    \mathsf b_\psi(P)=\frac{1}{d}|\langle\psi|P|\psi^*\rangle|^2.
\end{equation}
From this, one can see that, while the two distributions coincide in the special case of real states, they do differ in general.

For our purposes, the important point about the Bell distribution is that it will help us convert the structural properties of our states into a clear algebraic constraint on its support. Indeed, certain properties of $\rho$ will set certain probabilities $\mathsf b_\rho(P)$ to zero in some structured way. For instance, we will show that stabilizer and product structure, restrict the Bell distribution to live in some quadric defined by some binary matrix $M\in M_{2n}(\mathbb F_2)$ and the equation
\begin{equation}
     p^TMp=c,\quad\forall p\in\supp(\mathsf b_\rho)
\end{equation}
with $p\in\mathbb F_2^{2n}$ the symplectic representation of the Bell labels. We will prove this in the following section and develop it further to see how this helps in solving our problem.

\subsection{Quadratic symmetries of the Bell distribution}

For the moment, we will ignore sampling-complexity considerations and assume that we have access to the full support of the Bell distribution
\begin{equation*}
    \supp(\mathsf b_\rho)=\{q\in\mathbb F_2^{2n}:\mathsf b_\rho(P_q)\neq 0\}.
\end{equation*}
Our goal is to show how several structural properties of a state, such as purity, stabilizers, or product structure across hidden cuts, manifest as quadratic constraints on this support. To that end, let us consider the maximally mixed state $\rho=\mathbb I/d$, for which the Bell distribution looks completely unstructured:
\begin{equation}
    \mathsf b_{\mathbb I/d}(P)=\frac{1}{d}\Tr\!\left[P\frac{\mathbb I}{d}P\frac{\mathbb I}{d}\right]=\frac{1}{d^2}\qquad\forall P\in\mathcal P_n .
\end{equation}
Thus the Bell distribution is uniform over all $d^2$ Pauli labels, and there are no non-trivial support constraints.

For pure states the situation changes already. In that case, it can be shown that Bell outcomes belonging to the antisymmetric subspaces have zero probability, and thus one can't ever sample an odd number of singlets
\begin{equation}
    \ket{\Psi_{\text{singlet}}}=\frac{\ket{0,1}-
    \ket{1,0}}{\sqrt{2}}=\ket{\Phi_Y}.
\end{equation}
Since singlets are labeled by the antisymmetric single qubit $Y$ Pauli, in the $n$-qubit setting, this constraint means that $\mathsf b_\psi$ must be entirely supported on Bell states labeled by real Paulis. Indeed, one can show that for Paulis such that
\begin{equation}
    P^T=-P
\end{equation}
it must be that 
\begin{equation}
    \mathsf b_\psi(P)=0.
\end{equation}
This can be seen from looking at \Cref{eqn:pure_Bell}. Writing
\begin{equation}
    s=\bra{\psi}P\ket{\psi^*},
\end{equation}
since $s$ is a scalar, $s=s^T$ and therefore
\begin{align}
    s=s^T&=((\ket{\psi^*}^T)P\ket{\psi^*})^T\\&=((\ket{\psi^*}^T)P^T\ket{\psi^*})\notag\\&=\bra{\psi}P^T\ket{\psi^*}.\notag
\end{align}
If $P^T=-P$, then this implies $s=-s$ and hence $s=0$. Therefore
\begin{equation}
    \mathsf b_\psi(P)=0
    \qquad
    \text{whenever } P^T=-P .
\end{equation}


This constraint has a particularly transparent form as a quadratic symmetry in symplectic representation. In fact, write
\begin{equation}
    q=(x_1,z_1,\dots,x_n,z_n)\in\mathbb F_2^{2n}
\end{equation}
such that
\begin{equation}
    P_q=\prod_{i=1}^nX_i^{x_i}Z_i^{z_i}.
\end{equation}
Then a single-qubit factor is antisymmetric when both $x_i=z_i=1$. Thus the global parity of imaginary terms in the $n-$qubit case reads
\begin{equation}
    \sum_{i=1}^nx_iz_i=q^T\Omega_+q,\qquad \Omega_+=\bigoplus_{i=1}^n\begin{pmatrix}
        0 &1\\ 0& 0
    \end{pmatrix}.
\end{equation}
Hence the purity constraint can be written as the quadratic equation
\begin{equation}
    \label{eqn:purity_quadric}
    q^T\Omega_+q=0,\qquad \forall q\in\supp(\mathsf b_\psi).
\end{equation}
We can now make this discussion slightly more general in order to see how, for instance, product structure gives a direct refinement of the global purity case $\Omega_+$. We will also show that in fact stabilizers then arise as linear constraints of the same type.

For this, let $\rho$ be a generic $n-$qubit quantum state. Then, we can take any $M\in\text{Mat}_{2n}(\mathbb F_2)$ and define a quadratic symmetry on the Bell distribution such that
\begin{equation}
     q^TMq=c,\quad \forall q\in \supp(\mathsf b_\rho),
\end{equation}
where $c\in\mathbb F_2$ is constant. In order to help interpret these constraints we will show a direct translation between these quadratic Bell symmetries and symmetries in the Pauli distribution. Before doing so however, let us remind some basic facts of binary quadratic forms that will be useful for that.

Firstly, since we work over $\mathbb F_2$, every $M$ is totally determined by its associated bilinear form $B=M+M^T$ and its diagonal $v=\text{diag}(M),$ since  
\begin{equation}
    \label{eqn:quadratic_form}
    q^TMq=\sum_{i=1}^{2n}M_{i, i}q_i+\sum_{i<j}(M_{i, k}+M_{j , i})q_iq_j=\sum_{i=1}^{2n}M_{i, i}q_i+\sum_{i<j}B_{i, k}q_iq_j.
\end{equation}
 Thus, we can assume $M$ to be an upper triangular matrix, since for any symmetric term $S$, $M=M+S$ as quadratic forms. Moreover, the polar form $B$ is symmetric and alternating, and hence by standard results in classification of bilinear forms \cite{grove2002classical}, there exist some $A\in GL(2n,\mathbb F_2)$, such that
\begin{equation}
    A^{-T}BA^{-1}=\Omega^l\oplus 0_{2n-2l},\quad \Omega^l=\bigoplus_{i=1}^l\begin{pmatrix}
        0&1\\1&0
    \end{pmatrix}_i,
\end{equation}
and by \Cref{eqn:quadratic_form}, $A$ also block-diagonalises $M$ as a quadratic form, since for $M'=A^{-T}MA^{-1}$
\begin{equation}
    q^TM'q=\sum_{i=1}^{2n}M'_{i, i}q_i+\sum_{i<j}B'_{i, k}q_iq_j=q^T(v'+\Omega_+^l)q
\end{equation}
for $v'=\text{diag}(M')$, which is clearly block-diagonal. Hence, for all practical purposes
\begin{equation}
    \label{eqn:block_quadratic}
    M=A^{T}(\Omega^l_++v')A
\end{equation}
 We can now state our Lemma.

\begin{lemma}[{[Quadratic Bell symmetries induce Pauli constraints]}]
    \label{lemma:bell_to_Pauli}
    Let $\rho$ be an $n$-qubit state satisfying a quadratic Bell symmetry $M$. Then its Pauli distribution satisfies the following generalised purity equation
    \begin{equation}
        1=\frac{1}{2^l}\sum_{\substack{P\in\mathcal P_n:\\ \Omega p\in A^T{v'}+\mathrm{im}(M+M^T)}}\text{Tr}[P\rho]^2\cdot(-1)^{p^TN_Mp+c_{v'}+c}
    \end{equation} 
    for some quadratic symmetry $N_M$ given by 
    \begin{equation}
    \label{eqn:Pauli_symmetry}N_M=\Omega_++\Omega^TA^{-1}\big[\Omega_+^l+\Omega^lv'v'^T\Omega^l\big]A^{-T}\Omega
    \end{equation}
    and where $l=\frac{1}{2}\text{rank}(M+M^T)$, $A\in GL(2n,\mathbb F_2)$ is the block-diagonalising transformation, and $c_{v'}$ is an additional shift that depends on $v'$ coming from \Cref{eqn:block_quadratic}.
\end{lemma}

\begin{proof}

    First, the condition imposed by $M$ can be written as a generalized purity constraint on the Bell distribution. Namely,
    \begin{equation}
    1=\frac{1}{d}\sum_{\substack{Q\in\mathcal P_n:\\q\in  \supp(\mathsf b_\rho)}}\text{Tr}[Q\rho Q\rho^T]=\frac{1}{d}\sum_{Q\in\mathcal P_n}\text{Tr}[Q\rho Q\rho^T]\cdot(-1)^{q^TMq+c}
    \end{equation}
where in the last equality we have used that $\forall Q$ s.t. $q^TMq+c=1$, then $\text{Tr}[Q\rho Q\rho^T]=0$. 
Now, we can proceed by writing $\rho$ in the Pauli basis
\begin{equation}
    \rho=\frac{1}{d}\sum_{P\in\mathcal P_n} \text{Tr}[P\rho]P.
\end{equation}
Plugging this in the previous expression yields the following
\begin{align}
    1&=\frac{1}{d}\sum_{Q\in\mathcal P_n}\text{Tr}[Q\rho Q\rho^T]\cdot(-1)^{q^TMq+c}\\ 
        &=\frac{1}{d^2}\sum_{P,Q\in\mathcal P_n}\text{Tr}[P\rho]^2\text{Tr}[QPQP^T]\cdot(-1)^{q^TMq+c}\notag\\
        &=\frac{1}{d^2}\sum_{P,Q\in\mathcal P_n}\text{Tr}[P\rho]^2\cdot(-1)^{p^T\Omega_+p+q^T\Omega p}\cdot(-1)^{q^TMq+c}\notag\\
        &=\frac{1}{d^2}\sum_{P\in\mathcal P_n}\text{Tr}[P\rho]^2\cdot(-1)^{p^T\Omega_+p}\sum_{Q\in\mathcal P_n}(-1)^{q^T\Omega p+q^TMq+c},\notag
\end{align}
where following the previous notation $\Omega=\Omega^n$ is the standard symplectic form. Now we can analyze the sum over $Q$, for which is useful to write $M$ as in \Cref{eqn:block_quadratic}
\begin{align}
    \label{eqn:symmetry_translation}
    \sum_{Q\in\mathcal P_n}(-1)^{q^T\Omega p+q^TMq+c}&=\sum_{Q\in\mathcal P_n}(-1)^{q^T\Omega p+q^TA^T(\Omega_+^l+v')Aq+c}\\
        &=\sum_{Q\in\mathcal P_n}(-1)^{(A^{-1}q)^T\Omega p+q^T(\Omega_+^l+v')q+c}\notag\\
        &=\sum_{Q\in\mathcal P_n}(-1)^{q^T(v'+A^{-T}\Omega p)+q^T\Omega_+^lq+c}\notag\\
        &=\sum_{Q\in\mathcal P_n}(-1)^{q^Tv'_p+q^T\Omega_+^lq+c}\notag\\
        &=(-1)^c\prod_{i=1}^n\sum_{Q\in\mathcal P_1}(-1)^{q^T{v'}_p^i+q^T\Omega_+^{i_l}q}\notag
\end{align}
where in the second equality we have applied a change of basis on the Paulis, i.e., $q\leftarrow Aq$, and in the third and fourth equalities we have used that over $\mathbb F_2$ we have $a^2=a$, and thus
\begin{equation}
    q^Tv'q=\sum_{i=1}^{2n}v'_{i, i}q_i^2=\sum_{i=1}^{2n}v'_{i, i}q_i=q^T\cdot \vec v'
\end{equation}
and we can treat $v'$ as a vector (we will however write $v'$ instead of $\vec v'$ for ease of notation). Finally, in the last equality we take advantage of the block structure and factorise the sum into single qubit sums, and where $i_l=1$ if $i\leq l$ and $i_l=0$ otherwise. Then evaluating the single qubit sums yields the following result
\begin{equation}
    \label{eqn:sum_over_Q}
