\noindent{\large{\bf Methods}}\\
\noindent{\bf Provable small subsystem complexity}\\

An initial state $\psi$ thermalizes on a region $A$ if two conditions hold: \textit{equilibration} and \textit{temporal-thermal equivalence}. Equilibration means that with high probability, the reduced state $\psi_A(t)$ at late times approximates  $\bar \rho_A$ with a small bounded error, where $\bar \rho$ is the time average of $\psi(t)$. Equilibration provably follows from the non-degenerate gap condition and energy dispersion~\cite{Reimann2008,Linden2009}. Second, we say $\psi$ satisfies the $\varepsilon$-temporal-thermal equivalence on $A$ if $\bar \rho_A$ approximates the Gibbs state in $A$ to $\varepsilon$ trace distance. 

\begin{theorem}[Small subsystem complexity from energy dispersion and temporal-thermal equivalence]
    \label{thm:low-c-from-tte-ed}
    Let $H$ be a local Hamiltonian with non-degenerate spectral gaps, and $\psi$ be energy dispersed  with constant $\gamma$. For any positive constants $\alpha<\varepsilon<1$, if $\psi$ satisfies the $(\varepsilon/3)$-temporal-thermal equivalence at sufficiently high temperature on a contiguous region $A$ with $|A|/n\leq \frac{1}{2}(\gamma-\alpha)$, then, except for an $O(2^{-\alpha n})$ fraction of time $t\geq 0$,
        \begin{equation*}    \mathcal{C}_\varepsilon(\psi_A(t))\leq  \exp(\mathrm{polylog}(|A|)).
    \end{equation*}
\end{theorem}

Theorem~\ref{thm:low-c-from-tte-ed} assumes the temporal-thermal equivalence, which is generically expected, and can be proven in various contexts. In particular, it holds under a certain weak eigenstate thermalization hypothesis, which  can be proven in translation-invariant systems~\cite{Mori2016} for initial states drawn from an ensemble of random product states whose average is the Gibbs state~\cite{huang2020,Pilatowsky-Cameo2025}, such as $\mathcal{E}_0$ or the ensemble of stabilizer product states produced by the algorithm of Ref.~\cite{bakshi2025}. Specifically, we show that the equivalence is valid for $|A|\leq O(\log n)$ in translation-invariant systems for $\mathcal{E}_0$. See the SM~\cite{Supple} for details.

\vspace{1em}
\noindent{\bf Double-exponential temporal delocalization}\\

Here, we provide the proof of the following lemma, used in the proof of Theorem~\ref{thm:theorem1}.

\begin{lemma}[Double-exponential temporal delocalization]
    \label{thm:lemma1}
    For any Hamiltonian having spectral ergodicity, any initial state $\psi$ which is energy dispersed with $\gamma>0$, and any state $\sigma$ supported in $A$, except for an $\exp(-\exp(\alpha n))$ fraction of time with $\alpha\leq\gamma/8$,
    \begin{equation}
        D(\psi_A(t),\sigma)>\varepsilon
    \end{equation}
    for any subsystem $A$ with $|A|>(1-\gamma/8)n$ and $\varepsilon<1-\exp(-\Theta(n))$, where $D(\cdot,\cdot)$ denotes the trace distance. 
\end{lemma}

\begin{proof} For simplicity, let us focus here on the case where $A$ is the full system $|A|=n$ (the general proof is found in the SM~\cite{Supple}).
By Markov's inequality, the probability over time $t\in [0,\infty)$ is bounded, 
\begin{equation}\label{eq:nowhere-small-distance2}        
    \operatornamewithlimits{Pr}_t\bigl[D(\psi(t),\sigma)\leq \varepsilon\bigr]\leq M_k\,{(1-\varepsilon)^{-2k}},
\end{equation}
in terms of the $k$-th temporal moment  $M_k=\lim_{T\to \infty}\frac{1}{T}\int_0^T \dd t \langle\psi(t)|\sigma|\psi(t)\rangle ^k$, so we only need to bound these moments, for which we use our two assumptions. On the one hand, spectral ergodicity implies that upon time averaging, all off-diagonal non-resonating energy terms vanish~\cite{Mark2024},  allowing us to place a bound~\cite{Riddell2023},
\begin{equation}
    M_k\leq k!(\max_\mu p_\mu)^k 
\end{equation}   
in terms of the energy distribution $p_\mu=\abs{\braket{\mu}{\psi}}^2$. On the other hand, the energy dispersion guarantees that the maximum population is exponentially small: $\max_\mu p_\mu \leq 2^{-\gamma n/2}$. Combining both inequalities, the right-hand side of Eq.~\eqref{eq:nowhere-small-distance2} is upper bounded by
\begin{equation*}
    \frac{k! 2^{-\gamma nk/2}}{(1-\varepsilon)^{2k}}\leq \left(\frac{k 2^{-\gamma n/2} }{(1-\varepsilon)^2}\right)^k \leq \exp(-\exp(\alpha n)),
\end{equation*}
where the second inequality is due to Stirling's approximation, and the last one holds by choosing $k=e^{\alpha n}$ for any $\alpha< \gamma/4$ and sufficiently large $n\geq \Omega(\log(1/(1-\varepsilon)))$.\end{proof}

\vspace{1em}
\noindent{\bf Sufficient time for exponential complexity}\\

Here, we place a finite bound on the time $t_\mathrm{typ}$ required to reach the typical circuit complexity stated in Theorem~\ref{thm:theorem1}. To this end, we first make the notion of spectral ergodicity quantitative by introducing the \textit{$k$-th spectral gap $\Delta^{(k)}$}: the minimum difference $\abs{\sum_{i=1}^k E_{\mu_i} -\sum_{i=1}^k E_{\nu_i}}$ over all $k$-tuples of indices $(\mu_1,\dots,\mu_k)$ and $(\nu_1,\dots,\nu_k)$ which are not permutations of each other. The $k$-th no-resonance condition is simply the statement that $\Delta^{(k)}>0$. We prove that $t_\mathrm{typ}$ is at most proportional to $1/\Delta^{(k)}$, for an exponentially large $k$.
\begin{theorem}[Exponential quantum circuit complexity at finite time]
    For $H$ and $\psi$ as in Theorem~\ref{thm:theorem1}, and for a certain $T=\exp(\exp(O(n)))/\Delta^{(k_c)}$ with $k_c=\exp(\Theta(n))$, except for a double-exponentially small time fraction of $[0,T]$,
        \begin{equation*}
\mathcal{C}_\varepsilon(\psi(t))\geq  \exp \Omega(n).
\end{equation*}
\end{theorem}
\noindent This theorem implies that typical states at times of order $\exp(\exp(O(n)))/\Delta^{(k_c)}$ have exponentially large circuit complexity. This time scale gives an upper bound on $t_\mathrm{typ}$. 

While the $k$-th spectral gap is conceptually simple, to the best of our knowledge, no rigorous lower bound on $\Delta^{(k)}$ is known for generic local extensive Hamiltonians, even in the simplest cases of $k=1$ or $k=2$. We find that $\Delta^{(k)}$ decays approximately as $\exp(-\Theta(nk))$ based on a heuristic argument (see the SM~\cite{Supple}). Under this empirical scaling, choosing $k=\exp(\Theta(n))$ gives $1/\Delta^{(k)}=\exp(\exp(\Theta(n)))$, and hence $t_\mathrm{typ}\lesssim \exp(\exp(\Omega(n)))$. This double-exponential scaling is essentially the strongest one that can be obtained from any argument based on counting~\cite{Supple}.

