\section{Preliminaries}
\label{sec:01}
\subsection{Setting and basic notations}\label{sec:setting}
\newcommand{\supp}{\mathrm{supp}}

We consider a hypercubic lattice $\Lambda$ in $D$ dimensions, with $n$ vertices. For vertices $i,j\in\Lambda$, $d(i,j)$ denotes the minimum number of edges in a path connecting them. For regions $A,B\subseteq\Lambda$, $d(A,B)$ is defined by $\min_{i\in A,j\in B}d(i,j)$. We allow for periodic boundary conditions, by identifying the edges of the lattice. For a region $A\subseteq\Lambda$, its diameter is defined by $\mathrm{diam}(A)=\max_{i,j\in A} d(i,j)$, and the ball of radius $r$ centered at $j\in\Lambda$ is $B_r(j) = \{i\in\Lambda|d(i,j)\leq r\}$.
At each vertex, we place a qubit, associated with a two-dimensional local Hilbert space $\mathbb{C}^2$. The complete Hilbert space is simply the tensor product of all the local Hilbert spaces. 

For a matrix $A$, we denote by $\|A\|_1$ its trace norm, by $\|A\|_\diamond$ its diamond norm, and by $\|A\|_\mathrm{op}$ its operator norm $\sup_{\left\|\ket{\phi}\right\|=1}\left\|A\ket{\phi}\right\|$. The trace distance between two states $\rho$ and $\sigma$ is $D(\rho,\sigma)=\frac{1}{2}\|\rho-\sigma\|_1$. The fidelity is defined as $F(\sigma,\rho)\coloneqq\mathrm{tr}[(\sqrt{\sigma}\rho \sqrt{\sigma})^{1/2}]^2$. For matrices $A$ and $B$ having the same size, $A\preceq B$ means that $B-A$ is positive semi-definite.

\subsection{Asymptotic notation}
We utilize big-$O$ and related notations. We write $f(n)\leq O(g(n))$ to signify that there exist constants $C>0$ and $n_*>0$ with $f(n)\leq C g(n)$ for all $n\geq n_*$. Similarly $f(n)\leq e^{O(g(n))}$ means $f(n)\leq e^{C g(n)}$ for all $n\geq n_*$. For lower bounds we write $f(n)\geq \Omega(g(n))$ to mean $f(n)\geq  Cg(n)$ for all $n\geq n_*$ and  $f(n)\leq e^{-\Omega(g(n))}$ to mean $f(n)\leq e^{-C g(n)}$ for all $n\geq n_*$.  To combine both upper and lower bounds, we write $f(n)=\Theta(g(n))$, which means $f(n)\leq O(g(n))$ and  $f(n)\geq \Omega(g(n))$ simultaneously. 

\subsection{Quantum circuit complexity}
The circuit complexity of a pure state is the minimum number of basic gates required to construct it, starting from a product state. In this work, we utilize a more general notion of circuit complexity, also applicable to mixed states, based instead on local quantum channels.

Our elementary channels will be two-qubit quantum channels, whose support consists of at most two qubits. 
We define quantum circuit complexity of an $n$-qubit state by asking how many two-qubit channels are required to prepare the state, starting from a product state on $m$ qubits with $m\geq n$. The first $n$ qubits are the system qubits $\mathsf{S}$, while all remaining qubits are treated as ancilla qubits $\mathsf{R}$. We emphasize that our results are valid for an arbitrary choice of the number of ancilla qubits. We denote the set of all two-qubit quantum channels on the $m$-qubit system by
\begin{equation}
    \mathcal{G}=\{\mathcal{N}\,\colon\,|\supp(\mathcal{N})|\leq 2\}.
\end{equation} 

\begin{definition}[$\varepsilon$-robust circuit complexity]\label{def:circuit-complexity} 
We say that an $n$-qubit state $\rho$ has {\it $\varepsilon$-robust relative circuit complexity} $\mathcal{C}_{\varepsilon}(\rho|\sigma)=\mathcal{C}$ with respect to an $m$-qubit reference state $\sigma$, where $m\geq n$, if it can be approximated to trace distance $\varepsilon$ by the application of $\mathcal{C}$ two-qubit channels $\mathcal{N}_i\in\mathcal{G}$ starting from $\sigma$,
\begin{equation}
   \frac{1}{2}\Big\|\rho-\tr_\mathsf{R}(\mathcal{N}_{\mathcal{C}}\circ\mathcal{N}_{\mathcal{C}-1}\circ\cdots \circ\mathcal{N}_1[\sigma])\Big\|_1\leq \varepsilon,
\end{equation}
and $\mathcal{C}$ is the smallest number for which this decomposition holds. For $\varepsilon=0$, we say $\rho$ has {\it exact relative circuit complexity} $\mathcal{C}_0(\rho|\sigma)$ with respect to $\sigma$. We further define {\it $\varepsilon$-robust circuit complexity} $\mathcal{C}_{\varepsilon}(\rho)$ as the minimization of $\mathcal{C}_\varepsilon(\rho|\sigma)$ over the set $\mathcal{M}_m$ of all $m$-qubit product states $\sigma$ and all integers $m\geq n$,
\begin{equation}
    \mathcal{C}_{\varepsilon}(\rho) = \min_{m\geq n}\min_{\sigma\in\mathcal{M}_m}\mathcal{C}_{\varepsilon}(\rho|\sigma).
\end{equation}
\end{definition}
We make a few remarks about the ancilla qubits. First, a circuit consisting of $G$ two-qubit channels can act nontrivially on at most $2G$ qubits, and any ancilla qubits initialized in a product state and left untouched by the circuit have no impact on the system after being traced out. Therefore, it is sufficient to consider at most $2G$ ancilla qubits. Second, we may assume without loss of generality that the ancilla qubits are initialized in a fixed product state. This assumption does not affect either the set of states implementable using $G$ two-qubit channels or the circuit complexities in \Cref{def:circuit-complexity}, since arbitrary two-qubit channels already include the freedom to apply arbitrary single-qubit channels to any ancilla qubits that participate in the circuit. 

The space of states with complexity at most $G$ is highly intricate. Nevertheless, it can be made tractable by discretizing it via a covering net. We prove the following bound on the size of a covering net for the space of channels formed by $G$ two-qubit channels. The result below improves the $(\varepsilon/G)$-dependence of the covering number appearing in Lemma 18 of Ref.~\cite{raza2024}.
\begin{prop}[Lemma 18 of Ref.~\cite{raza2024}]\label{thm:two-qubit-covering-size}
    For any integer $G>0$ and any $\varepsilon>0$, consider the space of channels that can be constructed by concatenating $G$ two-qubit channels $\mathcal{G}_G=\big\{\mathcal{N}_G\circ \mathcal{N}_{G-1}\circ \cdots \circ \mathcal{N}_1\,\colon\, \mathcal{N}_i\in\mathcal{G}, i\in \{1,\dots,G\}\big\}$ acting on $m$ qubits with $m=n+2G$.
    There exists an $\varepsilon$-covering net $\{\mathcal{S}_1,\dots,\mathcal{S}_s\}\subseteq\mathcal{G}_G$ whose size $s$ is upper bounded by
    \begin{equation}
        s \leq ((n+2G)^2(1+512G/\varepsilon)^{256})^G.
    \end{equation}
    Specifically, this means that for any $\mathcal{N}\in \mathcal{G}_G$, we have $\norm{\mathcal{N}-\mathcal{S}_i}_{\diamond}\leq \varepsilon$ for some $i\in\{1,\dots,s\}$.
\end{prop}
\begin{proof}
Note that it is enough to construct an $(\varepsilon/G)$-covering net of the space $\mathcal{G}$ with size $ s \leq m^2 (1+512G/\varepsilon)^{256}$, by the subadditivity of the diamond norm under channel composition~\cite{haah2025}. To that effect, we first construct a covering net of the set of Choi states of the channels in the two-copy space $\mathcal{H}_A\otimes\mathcal{H}_B$. We then use H\"older's inequality to upper bound the diamond norm of a two-qubit channel $\Phi$ by the trace norm of its Choi state $J(\Phi)=\sum_{ij}\ketbra{i}{j}_A\otimes\Phi(\ketbra{i}{j}_B)$ as
\begin{equation}
    \begin{split}
        \|\Phi\|_\diamond 
        &= \max_{\substack{-\sigma\otimes I_B\preceq Y \preceq \sigma\otimes I_B\\ \tr(\sigma)=1}}\tr(Y J(\Phi))\\
        &\leq \max_{\substack{-\sigma\otimes I_B\preceq Y \preceq \sigma\otimes I_B\\ \tr(\sigma)=1}}\|Y\|_\infty \|J(\Phi)\|_1\\
        &\leq \|J(\Phi)\|_1.
    \end{split}
\end{equation}

The Choi state $J(\Phi)$ can be decomposed by Pauli strings $\{\hat{P}_a^{(A)}\otimes \hat{P}_b^{(B)}\}_{a,b}$ acting on $\mathcal{H}_A\otimes\mathcal{H}_B$ that are orthonormal under the Hilbert-Schmidt inner product as
\begin{equation}
    J(\Phi) = \sum_{a,b\in\{I,X,Y,Z\}^{\otimes 2}} c_{a,b} \hat{P}_a^{(A)}\otimes \hat{P}_b^{(B)}.
\end{equation}
Since $\Phi$ is a positive map, we have $J(\Phi)\succeq 0$. In addition, since $\Phi$ is trace-preserving, it follows that $\tr_B(J(\Phi))=I_A$. From these, we can compute $\|J(\Phi)\|_1$ as
\begin{equation}
    \|J(\Phi)\|_1 = \tr(J(\Phi)) = \tr(I_A) = 4.
\end{equation}
This can be used to upper bound the Hilbert-Schmidt norm as 
\begin{equation}
    \|J(\Phi)\|_2^2=\sum_{a,b\in\{I,X,Y,Z\}^{\otimes 2}} c_{a,b}^2 \leq \|J(\Phi)\|_1^2 \leq 4^2.
\end{equation}
Therefore, each coefficient $c_{a,b}$ should be in $[-4,4]$. 

Now, let us construct a hypercubic lattice $\Lambda_l$ with a spacing $l>0$ in the space of Hermitian matrices acting on $\mathcal{H}_A\otimes\mathcal{H}_B$,
\begin{equation}
    \Lambda_l = \left\{\sum_{a,b\in\{I,X,Y,Z\}^{\otimes 2}}(z_{a,b}l) \hat{P}_a^{(A)}\otimes \hat{P}_b^{(B)}\,\Big| \,z_{a,b}\in\mathbb{Z},z_{a,b}l\in[-4,4]\right\}.
\end{equation}
Then, for any two-qubit channel $\Phi$, there exists $J_\Lambda\in\Lambda_l$ such that
\begin{equation}
    \|J(\Phi)-J_\Lambda\|_1 \leq 4\|J(\Phi)-J_\Lambda\|_2 \leq 4\times\frac{l}{2}\times 4^2.
\end{equation}
From this, we can construct the covering net $S_\lambda$ of two-qubit channels as follows:
\begin{equation}
    S_\lambda = \left\{\Pi_\mathcal{G}(\tilde{J})\,\big|\,\tilde{J}\in\Lambda_l\right\}.
\end{equation}
Here, $\Pi_\mathcal{G}$ is defined as
\begin{equation}
    \Pi_\mathcal{G}(\tilde{J})=\operatornamewithlimits{argmin}_{\tilde{\Phi}\in\mathcal{G}}\|\tilde{J}-J(\tilde{\Phi})\|_2.
\end{equation}
Then, the distance between $\Phi$ and $\Phi_\Lambda=\Pi_\mathcal{G}(J_\Lambda)$ is upper bounded by
\begin{equation}
    \begin{split}
        \|\Phi-\Phi_\Lambda\|_\diamond
        &\leq\|J(\Phi)-J(\Phi_\Lambda)\|_1 \\
        &\leq 4\|J(\Phi)-J(\Phi_\Lambda)\|_2 \\
        &\leq 4\|J(\Phi)-J_\Lambda\|_2 + 4\|J_\Lambda-J(\Phi_\Lambda)\|_2\\
        &\leq 8\|J(\Phi)-J_\Lambda\|_2\\
        &\leq 8^2 l.
    \end{split}
\end{equation}
Therefore, by choosing $l$ as $\lambda/8^2$, $S_\lambda$ indeed becomes a $\lambda$-covering net of $\mathcal{G}$.

Finally, let us compute the size of the covering. Since $S_\lambda$ is induced from $\Lambda_l$, its size is equivalent to that of $\Lambda_l$, which is bounded by
\begin{equation}
    |\Lambda_l|\leq (1+8/l)^{4^4} = (1+512/\lambda)^{256}.
\end{equation}
By setting $\lambda=\varepsilon/G$, we get
\begin{equation}
    |S_{\varepsilon/G}|\leq (1+512 G/\varepsilon)^{256}.
\end{equation}

For an $m$-qubit system, there are $\binom{m}{2}\leq m^2$ pairs of qubits. Multiplying the right-hand side by this gives the stated upper bound on the covering size.
\end{proof}

\subsection{Hamiltonian}
We consider a Hamiltonian on a hypercubic periodic lattice of arbitrary dimension. For simplicity, let us expand it in the Pauli basis
\begin{equation}
\label{eq:paliexpansion}
    H=\sum_P c_P P.
\end{equation}
 We allow for periodic boundary conditions where the boundary qubits are identified. For simplicity, we assume $c_I=0$ so that $\tr(H)=0$, and additionally we will demand three physical properties of $H$ \cite{huang2024randomproduct}:

\begin{enumerate}
    \item[(P1)] {\it Locality}. There exists a constant $r$ (called the range of $H$), such that $c_P=0$ if the diameter of $\mathrm{supp}(P)$ is larger than $r$.
    \item[(P2)] {\it Extensivity}. There exists a constant $h_{\min}>0$ such that for any vertex $v$, a ball $B_r(v)$ of radius $r\geq 1$ centered at $v$ contains a term $|c_P| \geq h_{\min}$ which acts within the region $\mathrm{supp}(P)\subseteq B_r(v)$. 
    \item[(P3)] {\it Boundedness}. For all Pauli terms $P$ of $H$, $|c_P|\leq 1$.
\end{enumerate}

\subsection{Ensembles of product states}
\label{sec:Ensemblesofproductstates}
We are interested in the dynamics of generic, physical states, with initially low complexity, and ask how much complexity increases solely due to the unitary evolution generated by $H$. The most interesting case, to which we restrict our attention, is to study initial product states, which have trivial complexity. We define the ensemble of all product states, where each qubit is Haar random, as follows:
\begin{equation}\label{eq:rand-prod-state}
  \textit{{(Random product states ensemble)}}\qquad\qquad \mathcal{E}_0=\Big\{\bigotimes_{i=1}^n \ket{\psi_i} \, \Big | \ket{\psi_i}\sim \mathrm{Haar}(\mathbb C^2)\Big\}.
\end{equation}
Typically, a state $\ket{\psi}\sim \mathcal{E}_0$ will have an infinite effective temperature under $H$, but oftentimes the physical systems of interest have a finite effective temperature. To model such a situation we consider the ensemble of random product states whose energy falls inside a defined energy window. Specifically, for any inverse temperature $\beta$, we consider
\begin{equation}\label{eq:mc-prod-state}
  \textit{{(Product-state microcanonical ensemble)}}\qquad \mathcal{E}_{\beta,\delta}=\Big\{\ket{\psi}\sim\mathcal{E}_0 \, \Big |\, |\expval{H}{\psi}-E(\beta)|<\delta\sqrt{n}\Big\},
\end{equation}
where  $E(\beta)=\tr(\exp(-\beta H) H )/\tr(\exp(-\beta H))$ is the thermal energy. We will require that $\delta \geq 2^{2\mathcal{V}+1}$, where $\mathcal{V}\leq(2r+1)^D$ is the number of vertices inside a ball of radius $r$ in the lattice $\Lambda$. The parameter $\delta$ is otherwise arbitrary apart from this lower bound. 

\subsection{Finite correlation length of Gibbs state}
Throughout the paper, we denote the Gibbs state at inverse temperature $\beta$ by $g_\beta=\exp(-\beta H)/\tr(\exp(-\beta H))$. Later, we will restrict attention to temperatures for which $g_\beta$ has a finite correlation length. This property has been formalized as follows~\cite{Kliesch2014,Brandao2019,Bluhm2022,chen2025}.
\begin{definition}[Uniform clustering]
    Consider a bounded local Hamiltonian $H$. We say that $H$ is {\it uniformly clustering} at inverse temperature $\beta$ if for any $l\geq 0$, any region $X$, any reduced Hamiltonian in $X$, and any subregions $A\subseteq X$ and $C\subseteq X$ such that $d(A,C)\geq l$, we have
    \begin{equation}
        \abs{\mathrm{Cov}_{g_{\beta,X}}(O_A,O_C)}\leq\mathrm{poly}(|A|,|C|)e^{-l/\xi}
    \end{equation}
    for some correlation length $\xi>0$ and any operators $O_A$ and $O_C$ with unit operator norm supported on $A$ and $C$, respectively, where $g_{\beta,X}=\tr_{X^c}(g_\beta)$.
\end{definition}
This condition holds true in 1D at any temperature~\cite{Araki1969,Bluhm2022}, and in arbitrary dimension at high enough temperature, independent of system size~\cite{Kliesch2014,Capel2025}.

With these definitions, our main result is an unconditional statement guaranteeing that with probability exponentially close to unity, an initial product state sampled from the ensembles above has an exponentially large late-time complexity upon evolution under a generic, local Hamiltonian. 

In the next two sections, we will introduce two technical properties, one on the spectrum of the Hamiltonian, spectral ergodicity, and the other on the population in the energy eigenbasis of any state, called energy dispersion. We prove that these conditions are generic for local Hamiltonians and product states. Later, we will leverage these properties to prove a late-time exponentially large quantum circuit complexity. 

\section{Spectral ergodicity}
\label{sec:02}
Spectral ergodicity is a condition on the energy levels which allows one to compute infinite time averages and higher moments of states evolving unitarily under the Hamiltonian. We present the definition, and then we show that this property is satisfied generically for local Hamiltonians. 
\begin{definition}[$k$-th no-resonance condition and spectral ergodicity]
    Consider a Hamiltonian $H$ with energy levels $E_1,\dots,E_{2^n}$. For any integer $k>0$, we say $H$ satisfies the $k$-th no-resonance condition \cite{Kaneko2020,Mark2024,Riddell2023} if, for any two $k$-tuples of energy levels $(E_{\mu_1},\dots,E_{\mu_k})$ and $(E_{\nu_1},\dots,E_{\nu_k})$, their sums are equal
    \begin{equation}
        \sum_{i=1}^k E_{\mu_i}=\sum_{i=1}^k E_{\nu_i}
    \end{equation}
     if and only if the indices $(\mu_1,\dots,\mu_k)$ and $(\nu_1,\dots,\nu_k)$ constitute  permutations of each other. Whenever this is satisfied for arbitrary $k$, we say $H$ satisfies {\it spectral ergodicity}.
\end{definition}
\noindent We remark that the $k$-th no-resonance condition implies the $k'$-th no-resonance condition for all $k'\leq k$.

The $k$-th no-resonance condition has been leveraged as a basic assumption in many prior works studying dynamics of many-body systems~\cite{Kaneko2020,Mark2024,Riddell2023}. For $k=2$ this condition simply means the absence of gap degeneracies in the spectrum, which is a basic assumption present in most works that rigorously study quantum equilibration \cite{Reimann2008,Linden2009,Muller2015,Pilatowsky-Cameo2025}.  The notion of spectral ergodicity was leveraged in Ref.~\cite{Riddell2023} (under the name of \textit{generic spectrum}) to prove results on the concentration of quantum equilibration and recurrence times in dynamics.
\subsection{Proposition 1: Generic local Hamiltonians have spectral ergodicity}
Although expected to hold in general, the $k$-th no-resonance conditions have been difficult to prove. Reference~\cite{Huang2021} proved that generic local Hamiltonians have no gap degeneracies ($k=2$). Here, we generalize this result to generic local Hamiltonians for arbitrary $k$. We remark that Ref.~\cite{Riddell2023} proves that generic complex Hermitian matrices have spectral ergodicity. However, this result does not translate immediately to local Hamiltonians, since the set of local Hamiltonians has zero measure within the set of all complex Hermitian matrices.

\begin{prop}[Generic local Hamiltonians have spectral ergodicity; Proposition 1 in the main text]
